	potential := make([]int, n)
	dist := make([]int, n)
	prevv := make([]int, n)
	preve := make([]int, n)

	for {
		for i := 0; i < n; i++ {
			dist[i] = INF
		}
		dist[s] = 0
		inQ := make([]bool, n)
		queue := make([]int, 0)
		queue = append(queue, s)
		inQ[s] = true

		for len(queue) > 0 {
			v := queue[0]
			queue = queue[1:]
			inQ[v] = false
			for i, e := range graph[v] {
