	fmt.Fscan(in, &n, &m)

	total := n * m
	maxPairs := total / 2

	// store positions of each pair number (1..maxPairs)
	pos := make([][2]Pos, maxPairs+1)
	count := make([]int, maxPairs+1)

	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			var x int
			fmt.Fscan(in, &x)
			if count[x] == 0 {
				pos[x][0] = Pos{i, j}
			} else {
				pos[x][1] = Pos{i, j}
			}
			count[x]++
		}
	}

	// bipartite graph: left side = pairs, right side = edges (adjacent cells)
	// we will index edges and build adjacency list from pairs to edges
	edgeIndex := make(map[[4]int]int) // (r1,c1,r2,c2) sorted
	var edges [][2]Pos                // positions of the two cells of each edge

	// helper to add edge between two cells
	addEdge := func(a, b Pos) int {
		if a.r > b.r || (a.r == b.r && a.c > b.c) {
			a, b = b, a
		}
		key := [4]int{a.r, a.c, b.r, b.c}
		if idx, ok := edgeIndex[key]; ok {
			return idx
		}
		idx := len(edges)
		edgeIndex[key] = idx
		edges = append(edges, [2]Pos{a, b})
		return idx
	}

	// build all adjacency edges (grid neighbors)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if i+1 < n {
				addEdge(Pos{i, j}, Pos{i + 1, j})
			}
			if j+1 < m {
				addEdge(Pos{i, j}, Pos{i, j + 1})
			}
		}
	}

	E := len(edges)
	adj := make([][]int, maxPairs+1) // from pair to edges

	// for each pair, list edges that connect its two cells
	for p := 1; p <= maxPairs; p++ {
		a := pos[p][0]
		b := pos[p][1]
		// if already adjacent, there is an edge between them
		if abs(a.r-b.r)+abs(a.c-b.c) == 1 {
			idx := addEdge(a, b)
			adj[p] = append(adj[p], idx)
		}
	}

	// We need to build full adjacency: a pair can be assigned to any edge
	// that touches either of its cells. That corresponds to placing the pair
	// on that adjacent pair of cells.
	// So for each pair, for each edge, if one of its cells equals pair cell,
	// we add edge.
	for p := 1; p <= maxPairs; p++ {
		a := pos[p][0]
		b := pos[p][1]
		for eIdx, e := range edges {
			if (e[0] == a || e[1] == a) || (e[0] == b || e[1] == b) {
				adj[p] = append(adj[p], eIdx)
			}
		}
	}

	// maximum bipartite matching: left side 1..maxPairs, right side 0..E-1
	matchR := make([]int, E)
	for i := range matchR {
		matchR[i] = -1
	}

	var vis []bool
	var dfs func(int) bool
	dfs = func(u int) bool {
		for _, v := range adj[u] {
			if vis[v] {
				continue
			}
			vis[v] = true
			if matchR[v] == -1 || dfs(matchR[v]) {
				matchR[v] = u
				return true
			}
		}
		return false
	}

	matching := 0
	for u := 1; u <= maxPairs; u++ {
		vis = make([]bool, E)
		if dfs(u) {
			matching++
		}
	}

